-- Обновляем шаблон сообщения менеджеру в MAX на более профессиональный
UPDATE site_settings
SET value = E'━━━━━━━━━━━━━━━━━━━━━━\n🔔 *НОВАЯ ЗАЯВКА*\n*{company_name}*\n━━━━━━━━━━━━━━━━━━━━━━\n\n📋 *Заявка №* `{order_num}`\n📅 *Создана:* только что\n\n👤 *Клиент*\n├─ Имя: *{name}*\n├─ Телефон: *{phone}*\n└─ Email: {email}\n\n📍 *Адрес объекта*\n├─ Город: {city}\n└─ Адрес: {address}\n\n🔧 *Услуга*\n└─ {object_type}\n\n💰 *Сумма расчёта*\n└─ *{total} ₽*\n\n━━━━━━━━━━━━━━━━━━━━━━\n⚡ Свяжитесь с клиентом в течение 15 минут'
WHERE key = 'manager_max_template';

-- И шаблон клиенту тоже улучшим
UPDATE site_settings
SET value = E'✅ *Ваша заявка принята!*\n\n*{company_name}* благодарит вас за обращение, {name}.\n\n📋 *Номер заявки:* `{order_num}`\n\n⏰ Менеджер свяжется с вами в течение *15 минут*.\n\n📞 Срочные вопросы: {company_phone}\n🌐 Сайт: {company_email}\n\n_Сохраните этот номер заявки —\nон поможет быстро найти ваш заказ._'
WHERE key = 'client_notify_text';